import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type PictureInPictureIconProps=Omit<IconProps,"name">;
/** Lucide "picture-in-picture" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function PictureInPictureIcon(props:PictureInPictureIconProps){return <Icon name="picture-in-picture" {...props}/>;}
